tasks.solution:
function race(v1, v2, g) {
  if (v1 >= v2) return null;
  const totalSeconds = Math.floor((g / (v2 - v1)) * 3600);
  return [
    Math.floor(totalSeconds / 3600),
    Math.floor((totalSeconds % 3600) / 60),
    totalSeconds % 60,
  ];
}

